//! Model-based conformance: traces from the abstract model in `spec.rs` (generated by
//! stateright) and from `receipt_parking.qnt` (generated by Quint, as ITF) are replayed against
//! the real `SpiceDataManager`, checking each step's outcome and the abstracted state.

mod spec;

use super::*;
use near_primitives::block::Tip;
use spec::{Blk, COVERS, Msg, Op, Outcome, ParkingModel, State};
use stateright::{Checker, Model};
use std::fs;
use std::path::PathBuf;
use std::thread::available_parallelism;

/// Two chains from one two-shard genesis, with the validators of `chain_with_blocks`.
fn twin_chains() -> (Chain, Chain) {
    let validators: Vec<String> = (0..TOTAL_PARTS)
        .flat_map(|index| (0..2).rev().map(move |shard| shard_producer(shard, index).to_string()))
        .collect();
    let validators: Vec<&str> = validators.iter().map(String::as_str).collect();
    let genesis = TestGenesisBuilder::new()
        .genesis_height(0)
        .shard_layout(ShardLayout::multi_shard(2, 0))
        .epoch_length(10)
        .validators_spec(ValidatorsSpec::desired_roles(&validators, &[]))
        .build();
    let chain = get_chain_with_genesis(Clock::real(), genesis.clone());
    let twin = get_chain_with_genesis(Clock::real(), genesis);
    (chain, twin)
}

/// The real manager on a real chain, driven by model operations.
struct Real {
    chain: Chain,
    manager: TestManager,
    blocks: BTreeMap<Blk, Arc<Block>>,
    names: HashMap<CryptoHash, Blk>,
    commitment: SpiceDataCommitment,
    parts: Vec<SpiceDataPart>,
}

impl Real {
    fn new() -> Self {
        // The blocks are built on a twin chain of the same genesis so that their hashes exist
        // before the real chain stores them.
        let (chain, mut twin) = twin_chains();
        let genesis = chain.genesis_block();
        assert_eq!(genesis.hash(), twin.genesis_block().hash(), "twin genesis differs");
        let a = process_block_at(&mut twin, &genesis, 1);
        let b = process_block_at(&mut twin, &a, 2);
        let f = build_block_at(&twin, &a, 2);
        assert_ne!(b.hash(), f.hash(), "fork block equals its canonical sibling");
        let blocks = BTreeMap::from([(Blk::A, a), (Blk::B, b), (Blk::F, f)]);
        let names = blocks.iter().map(|(name, block)| (*block.hash(), *name)).collect();
        let manager = TestManager::new(&chain);
        let (commitment, parts) = encode_to_wire(&encoder(), &receipt_data(0, 1));
        Self { chain, manager, blocks, names, commitment, parts }
    }

    fn block(&self, b: Blk) -> &Arc<Block> {
        &self.blocks[&b]
    }

    fn name(&self, id: &DataId) -> Blk {
        self.names[id.block_hash()]
    }

    /// Applies `op`; returns the receive outcome or the blocks decoded at a trigger.
    fn apply(&mut self, op: Op) -> (Option<Outcome>, Vec<Blk>) {
        match op {
            Op::ChainAdd(b) => {
                let block = self.block(b).clone();
                process_block_sync(
                    &mut self.chain,
                    block.into(),
                    Provenance::PRODUCED,
                    &mut BlockProcessingArtifact::default(),
                )
                .unwrap();
            }
            Op::SetFinalHead(h) => self.manager.set_final_head(self.block(spec::canon(h))),
            Op::SetFinalExecutionHead(h) => {
                self.manager.set_final_execution_head(self.block(spec::canon(h)))
            }
            Op::SaveProof(b) => save_proof(&self.chain, self.block(b), &receipt_data(0, 1)),
            Op::Trigger(b) => {
                let hash = *self.block(b).hash();
                let output =
                    self.manager.manager.on_block_processed(&hash, self.manager.clock.now());
                let decoded = output.decoded.iter().map(|(id, _)| self.name(id)).collect();
                return (None, decoded);
            }
            Op::Receive(b, m) => {
                let id = receipt_id(self.block(b), 0, 1);
                let (signer, ordinal) = match m {
                    Msg::Producer(i) => (create_test_signer(producers()[i].as_str()), i as u64),
                    Msg::NonProducer => (create_test_signer(shard_producer(1, 0).as_str()), 0),
                    Msg::BadSig => (other_key_signer(&producers()[0]), 0),
                };
                let parts = parts_with_ordinals(&self.parts, &[ordinal]);
                let message = signed_by(&signer, &id, &self.commitment, parts);
                let outcome = match self.manager.manager.on_parts_received(message) {
                    Ok(PartsOutcome::Collecting) => Outcome::Collecting,
                    Ok(PartsOutcome::Decoded(_)) => Outcome::Decoded,
                    Ok(PartsOutcome::AlreadySettled) => Outcome::AlreadySettled,
                    Ok(PartsOutcome::NotWanted) => Outcome::NotWanted,
                    Err(SenderFault::NotAProducer) => Outcome::NotAProducer,
                    Err(SenderFault::InvalidSignature) => Outcome::InvalidSignature,
                    Err(fault) => panic!("fault outside the model: {fault:?}"),
                };
                return (Some(outcome), vec![]);
            }
        }
        (None, vec![])
    }

    /// Asserts the real manager's state abstracts to the model's, and the real-only invariants.
    fn assert_conforms(&self, model: &State, context: &str) {
        let m = &self.manager.manager;
        let tracked: BTreeSet<Blk> = m.items.keys().map(|id| self.name(id)).collect();
        assert_eq!(tracked, model.items.keys().copied().collect(), "tracked items; {context}");
        for (id, item) in &m.items {
            let expected = &model.items[&self.name(id)];
            let decoded =
                item.commitments.values().any(|state| matches!(state, CommitmentState::Settled));
            assert_eq!(decoded, expected.decoded, "decoded {id:?}; {context}");
            if !decoded {
                let bound: BTreeSet<usize> =
                    (0..3).filter(|index| item.producers[*index].commitment.is_some()).collect();
                assert_eq!(bound, expected.parts, "parts of {id:?}; {context}");
            }
        }
        let names = |ids: &HashSet<DataId>| -> BTreeSet<Blk> {
            ids.iter().map(|id| self.name(id)).collect()
        };
        assert_eq!(names(&m.delivered_items), model.delivered, "delivered; {context}");
        assert_eq!(names(&m.done_items), model.done, "done; {context}");
        let orphans: BTreeSet<Blk> = m.orphans.iter().map(|(hash, _)| self.names[hash]).collect();
        assert_eq!(orphans, model.orphans.keys().copied().collect(), "orphans; {context}");
        let processed: BTreeSet<Blk> =
            m.processed_blocks.keys().map(|hash| self.names[hash]).collect();
        assert_eq!(processed, model.processed, "processed blocks; {context}");
        // The height index names exactly the tracked items, each under its own height.
        let indexed: usize = m.items_by_height.values().map(HashSet::len).sum();
        assert_eq!(indexed, m.items.len(), "height index size; {context}");
        for (height, ids) in &m.items_by_height {
            assert!(!ids.is_empty(), "empty height index entry; {context}");
            for id in ids {
                assert_eq!(m.items[id].height, *height, "indexed height of {id:?}; {context}");
            }
        }
        // The store's heads are what the model's environment says.
        let store = self.chain.chain_store.store().chain_store();
        let final_head = store.final_head().map_or(0, |tip: Arc<Tip>| tip.height);
        assert_eq!(final_head, model.env_final_head, "store final head; {context}");
    }
}

/// Replays `ops` through the model and the real manager, comparing every step.
fn replay(name: &str, ops: &[Op]) {
    let mut real = Real::new();
    let mut model = State::default();
    real.assert_conforms(&model, &format!("{name}: initially"));
    for (step, op) in ops.iter().enumerate() {
        assert!(model.enabled(*op), "{name}: step {step} {op:?} is not enabled in the model");
        model = model.apply(*op);
        let context = format!("{name}: step {step} {op:?}, ops {ops:?}");
        let (outcome, decoded) = real.apply(*op);
        assert_eq!(outcome, model.last.outcome.map(|(o, _)| o), "outcome; {context}");
        assert_eq!(
            decoded,
            model.last.decoded_at.into_iter().collect::<Vec<_>>(),
            "decoded; {context}"
        );
        real.assert_conforms(&model, &context);
    }
}

/// The shortest trace stateright finds to each cover. Discoveries get overwritten by later
/// states, so the search deepens until each cover first shows up.
fn shortest_witnesses() -> BTreeMap<&'static str, Vec<Op>> {
    let mut shortest = BTreeMap::new();
    for steps in 1..=10 {
        let checker = ParkingModel
            .checker()
            .threads(available_parallelism().map_or(1, NonZeroUsize::get))
            .target_max_depth(steps + 2)
            .spawn_bfs()
            .join();
        for name in COVERS {
            if !shortest.contains_key(name) {
                if let Some(path) = checker.discovery(name) {
                    shortest.insert(name, path.into_actions());
                }
            }
        }
        if shortest.len() == COVERS.len() {
            break;
        }
    }
    shortest
}

#[test]
#[cfg_attr(not(feature = "protocol_feature_spice"), ignore)]
fn slow_test_stateright_cover_witnesses_conform() {
    let witnesses = shortest_witnesses();
    let missing: Vec<_> = COVERS.iter().filter(|name| !witnesses.contains_key(*name)).collect();
    assert!(missing.is_empty(), "covers without a witness: {missing:?}");
    for (name, ops) in &witnesses {
        println!("{name}: {ops:?}");
        replay(name, ops);
    }
}

fn quint_traces_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("src/spice/data_manager/tests/manager/model/quint_traces")
}

/// The operations of an ITF trace of `receipt_parking.qnt`, each with the outcome Quint recorded.
fn quint_ops(trace: &serde_json::Value) -> Vec<(Op, String)> {
    let str_of = |value: &serde_json::Value| value.as_str().unwrap().to_string();
    let int_of =
        |value: &serde_json::Value| value["#bigint"].as_str().unwrap().parse::<u64>().unwrap();
    trace["states"]
        .as_array()
        .unwrap()
        .iter()
        .skip(1)
        .map(|state| {
            let last = &state["last"];
            let block = || Blk::from_name(last["block"].as_str().unwrap());
            let op = match last["kind"].as_str().unwrap() {
                "chainAdd" => Op::ChainAdd(block()),
                "setFH" => Op::SetFinalHead(int_of(&last["h"])),
                "setFE" => Op::SetFinalExecutionHead(int_of(&last["h"])),
                "saveProof" => Op::SaveProof(block()),
                "trigger" => Op::Trigger(block()),
                "receive" => Op::Receive(block(), Msg::from_name(last["msg"].as_str().unwrap())),
                kind => panic!("unknown step kind {kind}"),
            };
            (op, str_of(&last["outcome"]))
        })
        .collect()
}

#[test]
#[cfg_attr(not(feature = "protocol_feature_spice"), ignore)]
fn quint_cover_witnesses_conform() {
    let mut paths: Vec<PathBuf> = fs::read_dir(quint_traces_dir())
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| path.to_string_lossy().ends_with(".itf.json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no quint traces");
    for path in paths {
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        let trace: serde_json::Value =
            serde_json::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        let steps = quint_ops(&trace);
        // The Quint model and the Rust model agree on every outcome...
        let mut model = State::default();
        for (op, quint_outcome) in &steps {
            model = model.apply(*op);
            let rust_outcome = model.last.outcome.map_or(String::new(), |(o, _)| format!("{o:?}"));
            assert_eq!(&rust_outcome, quint_outcome, "{name}: {op:?}");
        }
        // ...and the real manager agrees with both.
        let ops: Vec<Op> = steps.into_iter().map(|(op, _)| op).collect();
        println!("{name}: {ops:?}");
        replay(&name, &ops);
    }
}
